@event_class('Network.dataReceived')
@dataclass(slots=True)
class DataReceived:
    '''Fired when data chunk was received over the network.'''
    #: Request identifier.
    request_id: RequestId
    #: Timestamp.
    timestamp: MonotonicTime
    #: Data chunk length.
    data_length: int
    #: Actual bytes received (might be less than dataLength for compressed encodings).
    encoded_data_length: int
    #: *(Optional)* Data that was received. (Encoded as a base64 string when passed over JSON) *(EXPERIMENTAL)*
    data: str | None = None

    @classmethod
    def from_json(cls, json: T_JSON_DICT) -> DataReceived:
        return cls(
            request_id=RequestId.from_json(json['requestId']),
            timestamp=MonotonicTime.from_json(json['timestamp']),
            data_length=json['dataLength'],
            encoded_data_length=json['encodedDataLength'],
            data=json['data'] if json.get('data') is not None else None,
        )


