    def from_json(cls, json: T_JSON_DICT) -> DeviceBoundSessionEventOccurred:
        return cls(
            event_id=DeviceBoundSessionEventId.from_json(json['eventId']),
            site=json['site'],
            succeeded=json['succeeded'],
            session_id=json['sessionId'] if json.get('sessionId') is not None else None,
            creation_event_details=CreationEventDetails.from_json(json['creationEventDetails']) if json.get('creationEventDetails') is not None else None,
            refresh_event_details=RefreshEventDetails.from_json(json['refreshEventDetails']) if json.get('refreshEventDetails') is not None else None,
            termination_event_details=TerminationEventDetails.from_json(json['terminationEventDetails']) if json.get('terminationEventDetails') is not None else None,
            challenge_event_details=ChallengeEventDetails.from_json(json['challengeEventDetails']) if json.get('challengeEventDetails') is not None else None,
        )
